import{_ as n,H as s,f as p,i as e}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"45 | ARM新宠：苹果的M1芯片因何而快？","description":"","frontmatter":{},"headers":[{"level":2,"title":"CPU的原理初探","slug":"cpu的原理初探","link":"#cpu的原理初探","children":[{"level":3,"title":"ALU的需求梳理与方案设计","slug":"alu的需求梳理与方案设计","link":"#alu的需求梳理与方案设计","children":[]},{"level":3,"title":"自己动手用Verilog实现一个ALU","slug":"自己动手用verilog实现一个alu","link":"#自己动手用verilog实现一个alu","children":[]},{"level":3,"title":"验证测试ALU","slug":"验证测试alu","link":"#验证测试alu","children":[]}]},{"level":2,"title":"现代CPU加速的套路","slug":"现代cpu加速的套路","link":"#现代cpu加速的套路","children":[{"level":3,"title":"更多的硬件指令","slug":"更多的硬件指令","link":"#更多的硬件指令","children":[]},{"level":3,"title":"通过缓存来提高数据装载效率","slug":"通过缓存来提高数据装载效率","link":"#通过缓存来提高数据装载效率","children":[]},{"level":3,"title":"流水线乱序执行与分支预测","slug":"流水线乱序执行与分支预测","link":"#流水线乱序执行与分支预测","children":[]},{"level":3,"title":"多核心CPU","slug":"多核心cpu","link":"#多核心cpu","children":[]},{"level":3,"title":"超线程","slug":"超线程","link":"#超线程","children":[]}]},{"level":2,"title":"谈谈指令集","slug":"谈谈指令集","link":"#谈谈指令集","children":[{"level":3,"title":"CISC","slug":"cisc","link":"#cisc","children":[]},{"level":3,"title":"RISC","slug":"risc","link":"#risc","children":[]},{"level":3,"title":"ARM与M1芯片","slug":"arm与m1芯片","link":"#arm与m1芯片","children":[]}]},{"level":2,"title":"重点回顾","slug":"重点回顾","link":"#重点回顾","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"操作系统实战45讲/45-ARM新宠：苹果的M1芯片因何而快？.md","filePath":"操作系统实战45讲/45-ARM新宠：苹果的M1芯片因何而快？.md","lastUpdated":1779820584000}'),l={name:"操作系统实战45讲/45-ARM新宠：苹果的M1芯片因何而快？.md"};function i(t,a,c,o,r,d){return s(),p("div",null,[...a[0]||(a[0]=[e(`<h1 id="_45-arm新宠-苹果的m1芯片因何而快" tabindex="-1">45 | ARM新宠：苹果的M1芯片因何而快？ <a class="header-anchor" href="#_45-arm新宠-苹果的m1芯片因何而快" aria-label="Permalink to &quot;45 | ARM新宠：苹果的M1芯片因何而快？&quot;">​</a></h1><p>你好，我是 LMOS。</p><p>前面两节课，我们一起学习了虚拟机和容器的原理，这些知识属于向上延展。而这节课我们要向下深挖，看看操作系统下面的硬件层面，重点研究一下CPU的原理和它的加速套路。</p><p>有了这些知识的加持，我还会给你说说，为什么去年底发布的苹果M1芯片可以实现高性能、低功耗。你会发现，掌握了硬件的知识，很多“黑科技”就不再那么神秘了。</p><p>好，让我们正式开始今天的学习！</p><h2 id="cpu的原理初探" tabindex="-1">CPU的原理初探 <a class="header-anchor" href="#cpu的原理初探" aria-label="Permalink to &quot;CPU的原理初探&quot;">​</a></h2><p>经过前面的学习，我们已经对操作系统原理建立了一定认知。从操作系统的位置来看，它除了能够向上封装，为软件调用提供API（也就是系统调用），向下又对硬件资源进行了调度和抽象。我们通常更为关注系统调用，但为了更好地设计实现一个OS，我们当然也要对硬件足够了解。</p><p>接下来，我们一起看一看硬件中最重要的一个硬件——CPU是怎么工作的。让我们拆开CPU这个黑盒子，看一看一个最小的CPU应该包含哪些部分。不同架构的CPU，具体设计还是有很大差异的。为了方便你理解，我这里保留了CPU里的共性部分，给你抽象出了CPU的最小组成架构。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%9845%E8%AE%B2/images/409790/c2d0b75dffcfbdb5e72011013a6cd2d1.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%9845%E8%AE%B2/images/409790/c2d0b75dffcfbdb5e72011013a6cd2d1.jpg" alt=""></a></p><p>对照上图描绘的基本模块，我们可以把CPU运行过程抽象成这样6步。</p><p>1.众所周知，CPU的指令是以二进制形式存储在存储器中的（这里把寄存器、RAM统一抽象成了存储器），所以当CPU执行指令的时候，第一步就要先从存储器中取出（fetch）指令。</p><p>2.CPU将取出的指令通过硬件的指令解码器进行解码。</p><p>3.CPU根据指令解码出的功能，决定是否还要从存储器中取出需要处理的数据。</p><p>4.控制单元（CU）根据解码出的指令决定要进行哪些相应的计算，这部分工作由算术逻辑单元（ALU）完成。</p><p>5.控制单元（CU）根据前边解码出的指令决定是否将计算结果存入存储器。</p><p>6.修改程序计数器（PC）的指针，为下一次取指令做准备，以上整体执行过程由控制单元（CU）在时钟信号的驱动之下，周而复始地有序运行。</p><p>看了CPU核心组件执行的这6个步骤，不知道你有没有联想到 <a href="https://time.geekbang.org/column/article/369457" target="_blank" rel="noreferrer">第一节课</a> 的图灵机的执行原理？没错，现代CPU架构与实现虽然千差万别，但核心思想都是一致的。</p><h3 id="alu的需求梳理与方案设计" tabindex="-1">ALU的需求梳理与方案设计 <a class="header-anchor" href="#alu的需求梳理与方案设计" aria-label="Permalink to &quot;ALU的需求梳理与方案设计&quot;">​</a></h3><p>通过研究CPU核心组件的运行过程，我们发现，原来CPU也可以想象成我们熟悉的软件，一样能抽象成几大模块，然后再进行模块化开发。</p><p>因为从零开始实现一款CPU的工程量还是不小的，所以在这里我带你使用Verilog语言实现一个可以运行简单计算的ALU，从而对CPU具体模块的设计与实现加深一下认知。</p><p>首先，我们来思考一下，对于一个最简单的ALU这个模块，我们的 <strong>核心需求</strong> 是什么？</p><p>没错，聪明的你可能已经脱口而出了，我需要能 <strong>对两个N位的二进制数进行加减、比较运算</strong>。等等，为啥这里没有乘除？还记得学生时代初学乘除法的时候，老师也同样先简化为加减法，方便我们理解。</p><p>这里也一样，因为乘除也可以转换为循环的加减运算，比如2*3可以转换成2+2+2，6/2可以转换成6-2-2-2。所以，只需要实现了加减运算之后，我们就可以通过软件操作CPU，让它实现更复杂的运算了，这也正是软件扩展硬件能力的魅力。</p><p>好了，搞清楚需求之后，先不用着急编码，我们先来根据需求梳理一下ALU模块功能简图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%9845%E8%AE%B2/images/409790/1c53d14ef766154fb8a4627490f1ba03.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%9845%E8%AE%B2/images/409790/1c53d14ef766154fb8a4627490f1ba03.jpg" alt=""></a></p><p>首先，我们在模块左侧（也就是输入侧）抽象出了5根引脚，这五根引脚的作用分别是：</p><ul><li>ena：表示使能信号，它的取值是0或1可以分别控制ALU关闭或开启。</li><li>clk：表示时钟信号，时钟信号也是01交替运行的方波，时钟信号会像人的心跳一样驱动ALU的电路稳定可靠地运行。</li><li>opcode：表示操作码，取值范围是00、01、10这三种值，用来区分这一次计算到底是加法、减法还是比较运算。</li><li>data1、data2：表示参与运算的两个N位数据总线。</li></ul><p>现在我们再来看图片右侧，也就是输出侧的y，它表示输出结果，如果是加减运算，则直接输出运算后的数值，而比较运算，则要输出0、1、2，分别表示等于、大于、小于。</p><p>好了，有了方案，接下来就让我们想办法把方案变成可落地的实践吧。</p><h3 id="自己动手用verilog实现一个alu" tabindex="-1">自己动手用Verilog实现一个ALU <a class="header-anchor" href="#自己动手用verilog实现一个alu" aria-label="Permalink to &quot;自己动手用Verilog实现一个ALU&quot;">​</a></h3><p>Verilog是一种优秀的硬件描述语言，它可以用类似C语言的高级语言设计芯片，从而免去了徒手画门电路的烦恼。</p><p>目前Intel等很多著名芯片公司都在使用Verilog进行芯片设计。我们为了和业界保持一致，也采用了这种Verilog来设计我们的ALU。</p><p>在开发之前，你需要先进行一些准备工作，安装VSCode的Verilog语言支持插件、iverilog、gtkwave，这些工具安装比较简单，你可以自行Google搜索。</p><p>接下来，我们就来实现一下ALU的代码，也就是alu.v，代码如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/*----------------------------------------------------------------</span></span>
<span class="line"><span>Filename: alu.v</span></span>
<span class="line"><span>Function: 设计一个N位的ALU(实现两个N位有符号整数加 减 比较运算)</span></span>
<span class="line"><span>-----------------------------------------------------------------*/</span></span>
<span class="line"><span>module alu(ena, clk, opcode, data1, data2, y);</span></span>
<span class="line"><span>    //定义alu位宽</span></span>
<span class="line"><span>    parameter N = 32; //输入范围[-128, 127]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    //定义输入输出端口</span></span>
<span class="line"><span>    input ena, clk;</span></span>
<span class="line"><span>    input [1 : 0] opcode;</span></span>
<span class="line"><span>    input signed [N - 1 : 0] data1, data2; //输入有符号整数范围为[-128, 127]</span></span>
<span class="line"><span>    output signed [N : 0] y; //输出范围有符号整数范围为[-255, 255]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    //内部寄存器定义</span></span>
<span class="line"><span>    reg signed [N : 0] y;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    //状态编码</span></span>
<span class="line"><span>    parameter ADD = 2&#39;b00, SUB = 2&#39;b01, COMPARE = 2&#39;b10;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    //逻辑实现</span></span>
<span class="line"><span>    always&amp;#64;(posedge clk)</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        if(ena)</span></span>
<span class="line"><span>        begin</span></span>
<span class="line"><span>            casex(opcode)</span></span>
<span class="line"><span>                ADD: y &amp;lt;= data1 + data2; //实现有符号整数加运算</span></span>
<span class="line"><span>                SUB: y &amp;lt;= data1 - data2; //实现有符号数减运算</span></span>
<span class="line"><span>                COMPARE: y &amp;lt;= (data1 &amp;gt; data2) ? 1 : ((data1 == data2) ? 0 : 2); //data1 = data2 输出0; data1 &amp;gt; data2 输出1; data1 &amp;lt; data2 输出2;</span></span>
<span class="line"><span>                default: y &amp;lt;= 0;</span></span>
<span class="line"><span>            endcase</span></span>
<span class="line"><span>        end</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span>endmodule</span></span></code></pre></div><p>对照上面的代码块，我帮你挨个解释一下。首先我们定义了ALU简图左侧的5个引脚，对应到代码上就是抽象成了module的5个参数（是不是看起来很像一个C语言的函数）。</p><p>其次，为了能够临时保存运算结果，我们定义了寄存器y。</p><p>再然后，为了区别加、减、比较运算，我们定义了三种状态编码。代码中的always@其实是Verilog中的一个语法特性，表示输入信号的电平发生变化的时候，下边的代码块将会被执行。所以，这里实现的就是当时钟信号发生变化的时候，ALU就会继续执行。</p><p>再之后就是功能的实现啦，功能就是根据opcode将对应运算结果保存至寄存器y。你看，总共才30多行代码，我们就实现了一个可以计算任意N位二进制数的ALU，是不是很神奇？</p><h3 id="验证测试alu" tabindex="-1">验证测试ALU <a class="header-anchor" href="#验证测试alu" aria-label="Permalink to &quot;验证测试ALU&quot;">​</a></h3><p>作为一个严谨的工程师，我们除了编码之外，肯定还是要编写对应的测试用例，提升我们的代码的健壮性和可靠性。我们这就来一起编写一下对应的测试代码alu_t.v，代码如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/*------------------------------------</span></span>
<span class="line"><span>Filename: alu_t.v</span></span>
<span class="line"><span>Function: 测试alu模块的逻辑功能的测试用例</span></span>
<span class="line"><span>------------------------------------*/</span></span>
<span class="line"><span>\`timescale 1ns/1ns</span></span>
<span class="line"><span>\`define half_period 5</span></span>
<span class="line"><span>module alu_t(y);</span></span>
<span class="line"><span>    //alu位宽定义</span></span>
<span class="line"><span>    parameter N = 32;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    //输出端口定义</span></span>
<span class="line"><span>    output signed [N : 0] y;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    //寄存器及连线定义</span></span>
<span class="line"><span>    reg ena, clk;</span></span>
<span class="line"><span>    reg [1 : 0] opcode;</span></span>
<span class="line"><span>    reg signed [N - 1 : 0] data1, data2;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    //产生测试信号</span></span>
<span class="line"><span>    initial</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        $dumpfile(&quot;aly_t.vcd&quot;);</span></span>
<span class="line"><span>        $dumpvars(0,alu_t);</span></span>
<span class="line"><span>        $display(&quot;my alu test&quot;);</span></span>
<span class="line"><span>        //设置电路初始状态</span></span>
<span class="line"><span>        #10 clk = 0; ena = 0; opcode = 2&#39;b00;</span></span>
<span class="line"><span>            data1 = 8&#39;d0; data2 = 8&#39;d0;</span></span>
<span class="line"><span>        #10 ena = 1;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        //第一组测试</span></span>
<span class="line"><span>        #10 data1 = 8&#39;d8; data2 = 8&#39;d6;</span><span> //y = 8 + 5 = 14</span></span>
<span class="line"><span>        #20 opcode = 2&#39;b01;</span><span> // y = 8 - 6 = 2</span></span>
<span class="line"><span>        #20 opcode = 2&#39;b10;</span><span> // 8 &amp;gt; 6 y = 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        //第二组测试</span></span>
<span class="line"><span>        #10 data1 = 8&#39;d127; data2 = 8&#39;d127; opcode = 2&#39;b00;</span><span> //y = 127 + 127 = 254</span></span>
<span class="line"><span>        #20 opcode = 2&#39;b01;</span><span> //y = 127 - 127 = 0</span></span>
<span class="line"><span>        #20 opcode = 2&#39;b10;</span><span> // 127 == 127 y = 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        //第三组测试</span></span>
<span class="line"><span>        #10 data1 = -8&#39;d128; data2 = -8&#39;d128; opcode = 2&#39;b00;</span><span> //y = -128 + -128 = -256</span></span>
<span class="line"><span>        #20 opcode = 2&#39;b01;</span><span> //y = -128 - (-128) = 0</span></span>
<span class="line"><span>        #20 opcode = 2&#39;b10;</span><span> // -128 == -128 y = 0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        //第四组测试</span></span>
<span class="line"><span>        #10 data1 = -8&#39;d53; data2 = 8&#39;d52; opcode = 2&#39;b00;</span><span> //y = -53 + 52 = -1</span></span>
<span class="line"><span>        #20 opcode = 2&#39;b01;</span><span> //y = -53 - 52 = -105</span></span>
<span class="line"><span>        #20 opcode = 2&#39;b10;</span><span> //-53 &amp;lt; 52 y = 2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        #100 $finish;</span></span>
<span class="line"><span>    end</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    //产生时钟</span></span>
<span class="line"><span>    always #\`half_period clk = ~clk;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    //实例化</span></span>
<span class="line"><span>    alu m0(.ena(ena), .clk(clk), .opcode(opcode), .data1(data1), .data2(data2), .y(y));</span></span>
<span class="line"><span>endmodule</span></span></code></pre></div><p>在这个测试用例中，我们构造了一些测试数据来验证ALU模块功能是否正常，接下来我们就可以使用下面的命令对verilog源码进行语法检查，并生成可执行文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>iverilog -o my_alu alu_t.v alu.v</span></span></code></pre></div><p>生成了可执行文件之后，我们可以使用vvp命令生成.vcd格式的波形仿真文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vvp my_alu</span></span></code></pre></div><p>接下来，我们再把生成好的波形文件aly_t.vcd拖入gtkwave中，就能看到ALU模块仿真出的波形图了。</p><p>读到这里你可能会疑惑，难道verilog不支持像C语言一样动态调试每一行代码吗？为什么要仿真出波形文件呢？</p><p>其实verilog当然是支持动态调试的，只不过因为硬件芯片在实际运行过程中，有很多逻辑单元都可以并行，如果仅仅依靠动态调试来分析是很困难的。所以在实际开发过程中，我们会先模拟芯片真实运行时的信号波形来进行仿真，才能保证芯片的可靠性。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%9845%E8%AE%B2/images/409790/c3b905f03abe1daf6cf3f24fb54e41a9.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%9845%E8%AE%B2/images/409790/c3b905f03abe1daf6cf3f24fb54e41a9.jpg" alt=""></a></p><p>在仿真图波行的signals信号窗口，我们可以看到，ALU在每一个时刻入参和出参都和我们预期是一致的，这说明我们已经正确实现了一个N位的ALU模块。</p><h2 id="现代cpu加速的套路" tabindex="-1">现代CPU加速的套路 <a class="header-anchor" href="#现代cpu加速的套路" aria-label="Permalink to &quot;现代CPU加速的套路&quot;">​</a></h2><p>可能动手体会之后你还是意犹未尽，这是因为这样实现的模块其实还只是一个入门级的低性能ALU。上面的例子也只是为了帮你领会原理，因为追求极致的功耗、性能，所以现在我们使用的手机、电脑中的CPU基本上都不会设计得如此简单。</p><p>因此，如果想要更好使用CPU的机制来设计OS，我们还需要知道真实的工业级CPU如何解决问题，看看它们是如何做到动辄几GHZ的超高性能的。我为你梳理了常见的五种加速套路：</p><h3 id="更多的硬件指令" tabindex="-1">更多的硬件指令 <a class="header-anchor" href="#更多的硬件指令" aria-label="Permalink to &quot;更多的硬件指令&quot;">​</a></h3><p>我们前面实现的ALU只实现了三种功能，然而实际真实的CPU还会实现乘法、除法、逻辑运算、浮点数运算等等很多硬件指令。这样就可以在一个时钟周期内实现更多的功能，从而提高效率。</p><h3 id="通过缓存来提高数据装载效率" tabindex="-1">通过缓存来提高数据装载效率 <a class="header-anchor" href="#通过缓存来提高数据装载效率" aria-label="Permalink to &quot;通过缓存来提高数据装载效率&quot;">​</a></h3><p>在现代计算机体系中，由于磁盘、RAM、CPU寄存器之间的读写性能开销差别是非常大的，所以在现代CPU在设计的时候会在CPU内设计多级缓存，从而提高指令读写的速度。</p><h3 id="流水线乱序执行与分支预测" tabindex="-1">流水线乱序执行与分支预测 <a class="header-anchor" href="#流水线乱序执行与分支预测" aria-label="Permalink to &quot;流水线乱序执行与分支预测&quot;">​</a></h3><p>我们发现，前面抽象出的CPU运行的6个步骤其实是串行执行的，而现实世界却不一样，其实计算机内的很多算法可以不按顺序并行执行的。</p><p>既然提到了并行，不难联想到我们之前讲的多线程技术。但是多线程开发显然需要对程序做出更多优秀的设计，才能充分利用多核的性能，想要实现比较困难。</p><p>那么有没有办法，在不改造程序的前提下充分利用多核的资源呢？答案就是用 <strong>空间资源换时间</strong>。硬件层面把程序由解码器电路拆解成多步，调度到CPU的不同核心上并行、乱序执行。</p><p>比如，加法器在做加法运算的同时，乘法器不应该被闲置，应该也可以执行一些乘法指令。这样我们就可以把程序切分成多个可以并行运行的指令，以此来大幅提升性能了。</p><p>当然，形成流水线之后，理想情况就是所有被切分出来的指令都是正确的，这样就可以并行运算了。可惜事情并没有那么简单，因为我们的程序有可能走入了其他分支，后面的运算要依赖前边的结果才能运行。这时候，我们就需要引入分支预测器这个电路，尽可能猜对后面要执行的指令，这样正确切分指令从而提高并行度。</p><p>但一旦分支预测器预测失败，就需要重新刷新流水线，让指令顺序执行，这显然就会增加额外的时钟开销，造成性能损失。不过好消息是目前的分支预测器的准确率已经可以达到90%以上了。</p><h3 id="多核心cpu" tabindex="-1">多核心CPU <a class="header-anchor" href="#多核心cpu" aria-label="Permalink to &quot;多核心CPU&quot;">​</a></h3><p>随着单核心CPU的不断优化，我们会发现单核心下的CPU遇到了工艺等各种原因造成的瓶颈，很难再有更高的性能提升了。</p><p>所以，聪明的工程师又想到了提高并行度的经典套路，将多个CPU核心集成到了一颗芯片上。这时候每个CPU都有独立的ALU、寄存器、L1-L3多级缓存，但多个核心共用了同一条内存总线来操作内存。说到这里，反应快的同学可能会隐约感觉到哪里有些不妥了。</p><p>没错，因为内存中的数据被缓存到了CPU的多级缓存中，CPU的多个核心是并行操作数据的，这时如果没有额外的设计的保障机制，就很可能导致并行读写数据引起的数据一致性问题，也就是出现脏数据。</p><p>为了解决缓存一致性问题，工程师们又发明出了MESI、MOESI等缓存一致性协议来解决这个问题。</p><h3 id="超线程" tabindex="-1">超线程 <a class="header-anchor" href="#超线程" aria-label="Permalink to &quot;超线程&quot;">​</a></h3><p>我们发现前边整理的CPU核心组件的6个步骤，如果再进一步抽象，又可以简化的分为取指令和执行两部分。这时候我们发现，其实大部分指令在执行的过程中都不一定会占用所有的芯片资源的。</p><p>所以，出于尽可能的“压榨”硬件资源的考量，工程师们又设计了额外的逻辑处理单元用来保证多个可执行程序可以共享同一个CPU内的资源。当然，如果两个程序同时操作同一个资源（如某一个加法器）的时候，也是需要暂停一个程序进行避让的。</p><h2 id="谈谈指令集" tabindex="-1">谈谈指令集 <a class="header-anchor" href="#谈谈指令集" aria-label="Permalink to &quot;谈谈指令集&quot;">​</a></h2><p>从前面ALU的设计过程中，我们发现如果设计一个芯片模块，首先是要根据分析的需求抽象出对应的opcode等指令，而众多约定好的指令则构成了这款芯片的指令集。那么常见的CPU指令集都有哪些呢，让我们一起来看看吧。</p><h3 id="cisc" tabindex="-1">CISC <a class="header-anchor" href="#cisc" aria-label="Permalink to &quot;CISC&quot;">​</a></h3><p>复杂指令集Complex Instruction Set Computer简写为CISC，其实计算机早期发展的时候还是比较粗暴的，后来大家发现，让硬件实现更多指令可以有效降低软件运行时间，就疯狂地给硬件芯片设计工程师提需求。</p><p>于是越来越多的奇奇怪怪的指令被加入了CPU，最后指令不但越来越多，还越来越复杂。并且为了实现这些指令不但占用了大量的硬件资源，而且长度还不一致，这些都给以后的扩展以及性能优化挖了不少的坑。</p><p>挖坑总要后面填坑的，甚至Intel X86系列这个经典的CISC指令集的CPU，现在也是通过设计译码器，把变长的IA32指令翻译成简单的微代码，然后交给类似RISC的简单微操作来执行。这在某些层面上，也许也意味着CISC指令集巨头的一次叛逃。</p><h3 id="risc" tabindex="-1">RISC <a class="header-anchor" href="#risc" aria-label="Permalink to &quot;RISC&quot;">​</a></h3><p>精简指令集Reduced Instruction Set Computer，简写为RISC。经历了CISC指令集带来的问题，研究人员就对现代计算机运行的指令做了统计和分析，结果发现大部分的程序在大部分情况下，都在运行一小部分指令。</p><p>所以工程师就提出了一个大胆的假设，我们通过少部分相对简短且长度统一的指令集来替代CISC，这样同样能满足所有程序的需求。经过大量论证和实验后，人们发现这样不但解决了CISC指令带来的痛点，还带来了不少性能提升。</p><h3 id="arm与m1芯片" tabindex="-1">ARM与M1芯片 <a class="header-anchor" href="#arm与m1芯片" aria-label="Permalink to &quot;ARM与M1芯片&quot;">​</a></h3><p>后来ARM应运而生，ARM，是Advanced RISC Machine的缩写。看名字我们就知道。这是一个精简指令集的CPU。</p><p>早期很多CPU都是封闭的，要想设计一款新的CPU只能从头设计，这显然需要极高的成本投入。这时候ARM公司就抓住了市场痛点，ARM公司只做指令集和CPU的设计，然后付费授权（当然，授权费还是挺贵的）给各个厂商，由厂商根据自己的需求再去定制和生产。</p><p>由于ARM相对开放的态度，以及RISC指令集带来的高性能、低功耗、低成本特点，让它迅速从嵌入式领域杀进了移动设备、PC，甚至超级计算机领域。在2020年末，M1芯片一经上市测评数据便刷爆朋友圈，以致于Intel、AMD这些传统CPU在相同功耗的情况下性能被完全吊打，那么苹果到底使用了什么黑科技呢？</p><p>首先，苹果的M1芯片也是基于ARM架构的，它采用了AArch64架构的ARMv8-A指令集，是由台积电采用5nm工艺代工生产的，在芯片内集成了160亿个晶体管。显然，它在继承了ARM优点的同时，还能享受到更先进的芯片制程带来的高性能与低功耗。</p><p>而仅仅单纯继承ARM的优势其实还是不够的，因此M1芯片还额外引入了如增加解码器电路、统一内存架构、MCU等多种优化方式来进行设计。接下来，让我们来看一下苹果具体是如何做的：</p><p>根据我们之前提到了流水线和乱序执行的原理不难推断， <strong>解码器和CPU指令的缓冲空间大小会影响CPU的程序并行计算能力</strong>。</p><p>所以，苹果工程师在设计的时候，将解码器增加到了8个（而AMD、Intel的解码器一般只有4个）。同时，M1芯片的指令缓冲空间也比常见的CPU大了3倍。你可能会好奇，为啥X86系列的CPU不能多增加点解码器呢？</p><p>其实这就是ARM的RISC指令集的优势了。因为在ARM中，每条指令都是4个字节解码器，进行切分处理很容易；而X86的每条指令长度可以是1到15字节。这就导致了解码器不知道下一条指令是从哪里开始的，需要实际分析每条指令才可以，这就增加了解码器电路的复杂度。</p><p>有了提高并行能力的基础，多核心也是必须的。根据 <a href="https://www.anandtech.com/show/16252/mac-mini-apple-m1-tested" target="_blank" rel="noreferrer">AnandTech分享</a> 的资料来看，M1芯片内包含了4个3.2GHz的高性能Firestorm核心和4个0.6～2.064 GHz的低功耗Icestorm核心，这也为M1芯片在各种功耗下进行并行计算提供了基础。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%9845%E8%AE%B2/images/409790/1122c45ae261b067d20e38ede2023f0f.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%9845%E8%AE%B2/images/409790/1122c45ae261b067d20e38ede2023f0f.png" alt=""></a></p><p>我们观察上图可以发现M1芯片还集成了苹果自行设计的8个GPU核心。对手机芯片有了解的同学可能会觉得，高通之类的芯片也集成了GPU呀，这里有什么区别呢？其实这里引入了 <strong>统一内存</strong>（Unified memory）的设计。</p><p>传统的做法是如果CPU要和GPU之间传输数据，需要通过PCIe总线在CPU和GPU的存储空间内来回传递。</p><p>这就好比你有两个水杯，但互相倒水只能靠一个很细的吸管。而统一内存则是可以让CPU和GPU等组件共享同一块内存空间，这时候CPU要想传递数据，只需要写入内存之后通知GPU说：“嗨，哥们儿，你要的数据在某个地址空间，你自己直接用就好了。”这样就避免了通过PCIe总线传递数据的开销。</p><p>最后，我想提醒你注意这一点，它非常重要， <strong>严格讲，M1芯片其实并不是CPU</strong>。M1芯片其实是包含了CPU、GPU、IPU、DSP、NPU、IO控制器、网络模块、视频编解码器、安全模块等很多异构的处理器共同组成的系统级（SOC）芯片。</p><p>这样做的好处就是不需要在主板上通过各种总线来回传输数据，同时也避免了额外的信号、功耗开销。既然SOC的思路这么好，传统厂商为什么没有跟进呢？</p><p>原因在于商业模式不同，传统厂商生产CPU，但GPU、网卡、主板等模块是交由其他厂商生产，最终由专门的公司组装成一台计算机才对外销售。而Apple为代表的厂商的业务模式则是自己就有全产业链的整合能力，可以直接设计、交付整机。所以，不同的业务模式最终催生出了不同技术的方案。</p><h2 id="重点回顾" tabindex="-1">重点回顾 <a class="header-anchor" href="#重点回顾" aria-label="Permalink to &quot;重点回顾&quot;">​</a></h2><p>通过这节课的学习，我们明白了对于设计一款操作系统而言，对硬件的理解与把控能力非常重要。而硬件中很关键的一个组件就是CPU，我们一起分析了一个CPU的基本组成和运行步骤。</p><p>接着，为了把原理落地，我们一起实现了一个ALU，带你加深了对CPU原理的理解。之后我们还了解了现代CPU的发展历程以及设计思路，并分析了CISC、RISC指令的区别，以及基于ARM指令集的M1芯片的特点。</p><p>苹果的M1芯片，它在继承了ARM优点的同时，还做了很多优化，比如增加解码器提高并行计算能力，利用提高指令缓存空间的机制提升了指令加载与计算的效率，还引入了 <strong>统一内存</strong> 的巧妙设计。</p><p>在看到这些优势的同时，我们不妨发散思维，想一想为什么这些想法之前没有实现，这其实和业务模式息息相关。</p><p>最后，我特意为你梳理了这节课的导图，帮你巩固记忆。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%9845%E8%AE%B2/images/409790/0241c66ee023b45yy7f790e13bfe226e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%93%8D%E4%BD%9C%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%9845%E8%AE%B2/images/409790/0241c66ee023b45yy7f790e13bfe226e.jpg" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>除了ARM指令集，如果想开发一款CPU，我们还有更好的RISC指令集可选么？</p><p>欢迎你在留言区和我交流。也欢迎你把这节课分享给有需要的朋友，说不定就能帮他搞懂CPU的原理。</p><p>我是LMOS，我们下节课见！</p>`,110)])])}const g=n(l,[["render",i]]);export{u as __pageData,g as default};
